        )

    results = doc["results"]
    if not isinstance(results, list):
        raise TypeError(
            "results 必须是 list，得到 %s" % type(results).__name__
        )
    if len(results) != gate_count:
        raise ValueError(
            "results 长度必须等于 gate_count（%d），得到 %d"
            % (gate_count, len(results))
        )

    items = []
